import math


def loss_report(P, words):
    total, n = 0.0, 0
    for w in words:
        cs = "." + w + "."
        for a, b in zip(cs, cs[1:]):
            total -= math.log(P[index[a], index[b]])
            n += 1
    nats = total / n
    bits = nats / math.log(2)
    perplexity = math.exp(nats)
    return (round(nats, 4), round(bits, 4), round(perplexity, 4))

